bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}' 2>/dev/null)" = true || exit 61
test "$(docker ps --filter label=com.docker.compose.project=gace-createvdobot --filter label=com.docker.compose.service=videobot-poll -q | wc -l)" -eq 1 || exit 62
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'JS'
import pg from 'pg';
import {readFileSync} from 'node:fs';
import {setDefaultResultOrder} from 'node:dns';
import {setDefaultAutoSelectFamily} from 'node:net';
import {createCreatorTelegramFetch} from '/opt/videobot/src/runtime/creatorEgress.mjs';
import {createTelegramBotApi} from '/opt/videobot/src/telegram/botApi.mjs';
setDefaultResultOrder('ipv4first');
setDefaultAutoSelectFamily(false);
const env=process.env,pw=readFileSync('/run/secrets/videobot_db_password','utf8').trim();
const token=readFileSync('/run/secrets/videobot_telegram_token','utf8').trim();
const db=new pg.Pool({host:env.VIDEOBOT_DB_HOST,database:env.VIDEOBOT_DB_NAME,user:env.VIDEOBOT_DB_USER,password:pw,max:1,connectionTimeoutMillis:5000});
const transport=createCreatorTelegramFetch();
const api=createTelegramBotApi({token,fetchImpl:transport.fetch,timeoutMs:25000});
const fail=code=>{throw Object.assign(new Error(code),{code});};
try {
 const q=await db.query("SELECT a.delivery_key AS old_key,a.free_message_ids AS old_free,a.paid_message_id AS old_paid,b.delivery_key AS new_key,b.status AS new_status,b.free_message_ids AS new_free,b.paid_message_id AS new_paid,b.topic_id,l.title,l.description,l.price_stars,l.status AS listing_status FROM videobot_post_receipts a JOIN videobot_listings l ON l.listing_id=a.listing_id JOIN videobot_post_receipts b ON b.listing_id=l.listing_id AND b.revision=l.revision WHERE a.paid_message_id=4691 AND a.free_message_ids=ARRAY[4689,4690]::bigint[]");
 if(q.rowCount!==1)fail('RECEIPT_PAIR_INVALID');
 const r=q.rows[0];
 if(r.new_status!=='sent'||r.old_paid!=4691||!Array.isArray(r.new_free)||r.new_free.length!==2||r.new_free.some(id=>[4689,4690,4691].includes(Number(id)))||!['published','paused'].includes(r.listing_status))fail('RECEIPT_NOT_ELIGIBLE');
 if(!Number.isSafeInteger(r.price_stars)||r.price_stars<1||r.price_stars>25000||!Number.isSafeInteger(Number(r.topic_id)))fail('PRICE_TOPIC_INVALID');
 if(Number(r.topic_id)!==Number(env.VIDEOBOT_VIDEO_SALE_THREAD_ID))fail('TOPIC_CHANGED');
 const oldPurchases=await db.query("SELECT count(*)::integer AS n FROM videobot_stars_ledger WHERE delivery_key=$1 AND kind='paid'",[r.old_key]);
 if(oldPurchases.rows[0].n<1)fail('BUYER_PROTECTION_HISTORY_MISSING');
 const bot=await api('getMe',{});
 if(String(bot?.username||'').toLowerCase()!=='createvdobot')fail('BOT_IDENTITY_CHANGED');
 const chatId=-1002373696859;
 const first=Number(r.old_free[0]),paid=Number(r.old_paid);
 if(!Number.isSafeInteger(first)||!Number.isSafeInteger(paid)||first<=0||paid<=0||first===paid)fail('NEW_IDS_INVALID');
 const base=r.title+(r.description?'\n'+r.description:'');
 const paidCaption=base;
 const freeCaption=base;
 if(paidCaption.length>1024||freeCaption.length>1024)fail('CAPTION_LIMIT');
 const paidAck=await api('editMessageCaption',{chat_id:chatId,message_id:paid,caption:paidCaption});
 if(paidAck?.alreadyCurrent!==true && (paidAck?.message_id!==paid||paidAck?.caption!==paidCaption))fail('PAID_CAPTION_READBACK_FAILED');
 console.log('OLD_PAID_CAPTION_ONLY_CREATOR_TEXT=PASS');
 const freeAck=await api('editMessageCaption',{chat_id:chatId,message_id:first,caption:freeCaption});
 if(freeAck?.alreadyCurrent!==true && (freeAck?.message_id!==first||freeAck?.caption!==freeCaption))fail('FREE_ALBUM_CAPTION_READBACK_FAILED');
 console.log('OLD_FREE_ALBUM_CAPTION_ONLY_CREATOR_TEXT=PASS');
 console.log('PREEXISTING_PURCHASER_MEDIA_PRESERVED=PASS');
 console.log('NO_NEW_TELEGRAM_POSTS=PASS');
}catch(e){
 console.error('LINKED_POST_UPDATE=FAIL');
 process.exitCode=1;
}finally{
 await transport.close();await db.end();
}
JS
